from pathlib import Path

def count_py_files(directory):
    root = Path(directory)

    if not root.exists():
        raise FileNotFoundError(f"Directory does not exist: {root}")
    if not root.is_dir():
        raise NotADirectoryError(f"Not a directory: {root}")

    return sum(1 for path in root.rglob("*.py") if path.is_file())

# Example usage
print(count_py_files("/path/to/directory"))
```

`Path.rglob("*.py")` searches recursively, and `path.is_file()` ensures only files are counted.

